// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, uniqueSuffix } from '@skyramp/skyramp';
import { createMember, getMemberGrowth } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:2368");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const start_date = new Date().toISOString().slice(0, 10);
    const probeEmail = uniqueSuffix("growth-probe@example.com");

    const membersPostResponse = await createMember(client, headers, probeEmail);

    expect(getValue(membersPostResponse, "members.0.email"), 'email').toBe(probeEmail);
    expect(getValue(membersPostResponse, "members.0.name"), 'name').toBe("Growth Probe Member");
    expect(getValue(membersPostResponse, "members.0.status"), 'status').toBe("free");
    expect(getValue(membersPostResponse, "members.0.created_at"), 'created_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const memberGrowthGetResponse = await getMemberGrowth(client, headers, start_date, start_date);

    expect(getValue(memberGrowthGetResponse, "start_date"), 'start_date').toBe(start_date);
    expect(getValue(memberGrowthGetResponse, "end_date"), 'end_date').toBe(start_date);
    expect(getValue(memberGrowthGetResponse, "analytics").length, 'analytics length').toBe(1);
    expect(getValue(memberGrowthGetResponse, "analytics.0.date"), 'date').toBe(start_date);
    expect(getValue(memberGrowthGetResponse, "analytics.0.count"), 'count').toBeGreaterThanOrEqual(1);
    expect(getValue(memberGrowthGetResponse, "analytics.1"), 'analytics.1').toBeUndefined();
});
